            measurement.achieved_dl_kbps = Some(proposal.download.observed_low_kbps.max(1));
            measurement.realized_dl_kbps = realized_dl_kbps;
            measurement.load_reference_dl_kbps = Some(proposal.download.maximum_kbps);
